#!/usr/bin/env bash
# scripts/check_doctrines.sh — THE GENERAL DOCTRINE ENFORCER (driver + registry).
#
# PGEN-DIAG-TOOLBOX-0002. Director directive (2026-06-22): make doctrine compliance
# "provable, trackable ... so we do not have to trust your words — rule enforcers that
# literally force the rule, no matter what." This is the single driver that runs EVERY
# mechanizable doctrine check, reports per-doctrine PASS/FAIL, and exits NONZERO on any
# breach. It formalizes the previously ad-hoc `.githooks/pre-commit` check stack into one
# registered, self-reporting framework.
#
# Enforcement layering (MEMORY_ARCHITECTURE.md §9 — defense in depth):
#   E1 discovery   : the doctrine docs (README, TOOLBOX.md, docs/decisions/, the books).
#   E2 self-check  : THIS script + each registered scripts/check_*.sh (single source of truth).
#   E3 git hook    : .githooks/pre-commit calls this (fast local gate; activated via
#                    `git config core.hooksPath .githooks`).
#   E4 CI          : the same script runs server-side (un-bypassable backstop) — invoked by
#                    `.github/workflows/memory-architecture-gate.yml`, the one workflow that
#                    still runs on `push`/`pull_request`. ⭐ IT MUST INVOKE THIS DRIVER, NOT
#                    INDIVIDUAL ENFORCERS: it named five of them until 2026-07-29
#                    (CI-PARITY-GATE-ROT.15), so 8 of the 13 registered doctrines had NO
#                    automatic lane and a doctrine added tomorrow silently got none. The
#                    registry is the single source of the roster, so calling the driver makes
#                    a new doctrine inherit the lane by construction. `FLOW-INTEGRITY`
#                    invariant (8) enforces that; the other 14 workflows stay manual-only
#                    (workflow_dispatch) to conserve Actions minutes.
#                    HONEST GAP: a local hook can be `--no-verify`'d, and the four
#                    STAGED-SCOPE doctrines below evaluate nothing on a hosted push — which
#                    this driver now SAYS rather than passing silently.
#
# What "provable / not trust-me-bro" means here, honestly:
#   - STRUCTURAL doctrines (memory-arch, docpaths, ebnf-SoT, knowledge-map) — the check
#     re-derives the invariant from the tree; pass/fail is a fact about the files.
#   - DETERMINISTIC-ORACLE doctrines (cert-coverage, ast_shape_contract, syntax-closure —
#     run by the broader make gates / CI) re-RUN the real tool at fixed seeds, so a claimed
#     number that does not reproduce FAILS. This is the strongest leg.
#   - EVIDENCE doctrines (diag-toolbox-evidence) require a re-checkable artifact (pasted tool
#     output) in the owning task leaf. A hook cannot prove the agent REASONED from it, but it
#     makes landing a code change with no pasted, reproducible tool output impossible at the gate.
#
# Registry below = the source of truth for "which doctrines are enforced by what". The
# human-readable mirror is DOCTRINE_ENFORCEMENT.md §10 (kept in lockstep).
set -uo pipefail   # deliberately NOT `-e`: run ALL checks, collect every result, then report.
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
# ⛔ Resolve THIS FILE absolutely BEFORE the cd. `<meta:registry-escaping>` below reads the
# driver's own SOURCE TEXT, and a relative `${BASH_SOURCE[0]}` stops resolving the moment the cwd
# moves — the arm then inspects nothing and PASSES, which is the failure direction this whole
# driver exists to close. MEASURED: the RED control fired exactly that way on its first run.
SELF="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/$(basename "${BASH_SOURCE[0]}")"
cd "$ROOT"

# Each entry: "ID|what it proves|relative/path/to/check.sh"
# Add a new doctrine here AND in docs/decisions/DOCTRINE_ENFORCEMENT.md (a meta-check below
# asserts every registered enforcer exists + is executable, so a registry entry cannot be a
# dangling promise).
DOCTRINES=(
  "MEMORY-ARCH|durable 4-layer memory architecture invariants (MEMORY_ARCHITECTURE.md §9), incl. layer A bounded by BOTH a line cap and a byte cap — the line-only form passed 60 lines / 138,403 bytes (README-POLICY.2)|scripts/check_memory_architecture.sh"
  "DIAG-SEVERITY+DOCPATH|severity never masked by verbosity + repo-root-relative live-doc paths|scripts/check_diagnostics_and_docpaths.sh"
  "EBNF-SOURCE-OF-TRUTH|no new out-of-band acceptance validator wired outside the EBNF|scripts/check_ebnf_source_of_truth.sh"
  "REGEX-SELF-HOSTING|the regex grammar self-hosts (gen<->parse duality holds)|scripts/check_regex_self_hosting.sh"
  "KNOWLEDGE-MAP|the derived Knowledge Map is in sync with its fact sources|knowledge-map/scripts/check_knowledge_map.sh"
  "TASK-ACCEPTANCE|a code change's task leaf passes the acceptance checklist (root-cause + addressed + no-regression boxes ticked + evidence-backed) A PRODUCER A DOCTRINE READS IS PART OF THE PROOF SURFACE TOO, AND THE SET IS DERIVED, NEVER HAND-LISTED (SV-CORPUS-GRAD.13l): the code-change classifier admits every stimuli script the registry's oracles reference, two hops deep, computed from the registry's SCRIPT column on every run -- stimuli/run_external_corpus.sh emits the reports CORPUS-CENSUS-CURRENCY re-derives, corpus_verdict_coverage.py emits what SV-CORPUS-DENOMINATOR re-derives, and the adjudicator arrives via the runner without anyone typing its name. Priced over the whole history as a widening must be: 3 251 commits, 34 staged a producer and no other in-scope path. The first cut globbed scripts/check_*.sh, read its OWN comment naming two helpers as negative examples, and admitted them -- a census that can read the sentence about the census is not a census -- so the oracles are the registry's data column with the classifier itself excluded; and under set -e a grep finding nothing inside a command substitution killed the derivation to an EMPTY set while two RED arms passed for the wrong reason, both caught by the bank docs/tasks/artifacts/sv_corpus_grad/producer_admission/probe.sh before shipping. --producers prints the derived set with each member's referencing oracle so the population is inspectable, and every arm of that bank applies and reverts its staged mutation inside one trap|scripts/check_diagnosis_evidence.sh"
  "REGEX-ORACLE-ANCHOR-SYNC|the live oracle-tuple anchors agree with each other + the tracked ratchet bounds|scripts/check_regex_oracle_anchor_sync.sh"
  "LESSON-PROMOTION|a durable lesson written to DEVELOPMENT_NOTES.md is either PROMOTED into the retrievable layer or EXPLICITLY DECLINED, never silently dropped — the promotion mechanism existed, was wired, and was skipped 1592 times because no gate asked (LESSON-RETRIEVAL.4; KNOWLEDGE-MAP checks the map is in sync with its SOURCES, never that a lesson REACHED a source)|scripts/check_lesson_promotion.sh"
  "DESIGN-PRIOR-ART|a task leaf proposing a NEW annotation/directive surface records a prior-art search first (docs/decisions/feedback_read_prior_art_before_designing.md)|scripts/check_design_prior_art.sh"
  "WAIVER-ROUTING|a task leaf claiming a gate does not apply names the leaf that owns fixing the gate (an unrouted waiver is a bug report about the gate, left inert)|scripts/check_waiver_routing.sh"
  "ROUTING-EVIDENCE|a task leaf routing a finding OUT to another tree records what it MEASURED — above all whether the finding reproduces outside the family it is being sent to (CI-PARITY-GATE-ROT.9: a shared-gate defect was routed to the regex family on a plausible reading, and the deciding evidence was already on disk)|scripts/check_routing_evidence.sh"
  "DESTRUCTIVE-TARGET-GUARD|destructive make targets refuse without PGEN_CONFIRM_CLEAN=1 + no innocuous alias routes into them (OPS-MEMSAFE.3)|scripts/check_destructive_target_guard.sh"
  "GATE-REACHABILITY|every tracked gate target is invoked by something that RUNS, or carries a deliberate disposition — a check nothing invokes is indistinguishable from one that does not exist (CI-PARITY-GATE-ROT.2)|scripts/check_gate_reachability.sh"
  "FLOW-INTEGRITY|the gate flow cannot drift back: workflows that need generated parsers regenerate them and budget for it, the recipe keeps one home, artifact hand-offs never point at a standalone default, no assertion requires a defect to pass, hand-off provenance coverage only improves (CI-PARITY-GATE-ROT.8), the doctrine roster keeps an AUTOMATIC lane through THIS driver rather than a re-typed list of enforcers (CI-PARITY-GATE-ROT.15), a guard tests the artifact it actually READS (CI-PARITY-GATE-ROT.14), the SHIPPING generation recipe stays QUIET — no tracked Makefile invokes --generate-parser carrying --debug/--trace, which cost 6.89 GB of log per regeneration for artifacts the flags provably cannot change (CI-PARITY-GATE-ROT.31, director-ruled), and every EBNF→json rule is guarded against GNU Make 3.81's WHOLE-SECOND mtime comparison, which silently skips a rule whose prerequisite was rewritten in the same second — measured 5 of 10 families exposed on the grammar→json edge and 10 of 10 on json→parser (CI-PARITY-GATE-ROT.32)|scripts/check_flow_integrity.sh"
  "PARSER-BOOK-CURRENCY|a per-parser BOOK publishes the release its family actually SHIPS, in BOTH directions, over a CLOSED population of all ten books — the book is the director's stated review surface (\"my only window into the project — I review the book, not the code\"), and it sat in the seam between the three existing currency doctrines: PUBLISHED-VERSION-CURRENCY holds the regex identity pair and the per-family STATUS row, LIVE-DOC-CURRENCY classifies by date spread, SV-CONTRACT-CURRENCY holds the CONTRACT current with the GRAMMAR, and none of them compares a family book against its family's release (SV-CORPUS-GRAD.13c.2z; measured 2026-08-21: the SystemVerilog book published 1.0.183 against a shipped 1.0.192 and schema 20 against 25 — nine releases and five schemas invisible — and this was the SECOND occurrence, the first having been hand-reconstructed with a prose warning naming the contract as the winner, which bought exactly one cycle before the same sentence drifted a third time). ⛔ The population is CLOSED and every book is CLASSIFIED, because sizing it first is what found the other two: vhdl was a release stale and systemverilog_preprocessor uses a heading convention a SystemVerilog-shaped regex reads as an EMPTY book|scripts/check_parser_book_currency.sh"
  "PUBLISHED-VERSION-CURRENCY|the user guide's published regex identity pair equals the contract's Contract Identity block and its published family status equals the live tracker row — a Provisional/any parser SHIPS on its published state, so the published state must be gate-held true (DONE-BAR.5a; measured ~77 releases stale with no gate reading it)|scripts/check_published_version_currency.sh"
  "LIVE-DOC-CURRENCY|a live document is currently TRUE, not merely bounded: instrument A counts DISTINCT dates per surface PAIRED WITH ITS DECLARED CHARTER (so it classifies rather than alarms — CHANGES.md scores in the hundreds of distinct dates and is correct; the count is the instrument's own output on every run and is never stored here, SV-CORPUS-GRAD.13v), instrument B catches a self-declared \`Last updated:\` refuted by the file's own newest content date (no baseline, no threshold), and route closure requires every .md destination a capped enforcer NAMES to be a watched surface — the unwatched-overflow edge is how LIVE_ACHIEVEMENT_STATUS.md reached 1 547 057 B beside a README capped on two axes (LIVE-MEANS-LIVE.2). ⛔ B REFUSES on any unclassified declaration spelling rather than enumerating spellings: enumeration is what made the same population measure 10, then 16, then 18, every miss silent in the passing direction|scripts/check_live_document_currency.sh"
  "SV-CORPUS-DENOMINATOR|the SV corpus DENOMINATOR is re-derived and published beside the defect bar -- and, since SVPP-EXPANSION.6c.1, so is the same tuple READ UNDER THE PIPELINE (pipeline_coverage.tsv, the re-adjudication table's verdicts bucketed; the raw tuple stays first): the tracked verdict-coverage artifacts are byte-identical to a fresh census re-run, and every designated live surface carries the derived adjudicated/routed/no-verdict/dark/bar tuple — a bar without its denominator is not a claim about the corpus (SV-CORPUS-GRAD.13b; the artifact was MEASURED stale one day after landing, published bar 319 vs HEAD's 318, with NOTHING in the repo invoking the instrument)|scripts/check_sv_corpus_denominator.sh"
  "PARSE-COST-RATCHET|the SV parser's parse COST is measured and cannot rise unwatched: the tracked baseline's instrument identity (grammar + generated parser + instrument + a digest of the sampled corpus files) is re-hashed every run alongside FOUR more every-run arms — the LR-family classifier over all ten generated parsers, the published corpus family share re-hashed against its tracked derivation, and CO-PUBLICATION of that derived share on every designated live surface (ENGINE-UNIVERSAL-SERVICES.21 (f)), plus the PROBE FINGERPRINT: those four identity rows are all SOURCES, while the numbers are produced by an untracked probe binary nothing hashed, so rust/build.rs now sha256s every generated parser it already rerun-if-changed's and the probe reports which one it embeds — a gap that failed in the PASSING direction, since a probe built from a guard-suppressed arm reported 762,345 rule entries against the shipped parser's 11,240,430 and a FALL is not a breach here but an invitation to rebaseline (ENGINE-UNIVERSAL-SERVICES.24) — and a re-measure refuses on any rise in the binding counters — entries / committed / memo-hits, each verified deterministic and build-mode-independent before being made binding (ENGINE-UNIVERSAL-SERVICES.20 acceptance (d); the guarded admission shipped while the lint, the two-sided repro ratchet, the corpus pass/fail count and every registered doctrine stayed GREEN, because nothing measured parse cost at all — it cost +10.59 % rule entries, and the +24.3 % PARSE TIME this doctrine was founded on is REFUTED by .20 slice 5 as a fixed-arm-order artifact, which is the argument FOR a re-derivable ratchet, not against one; .26 retired the blind-spot factor built on it)|scripts/check_parse_cost_ratchet.sh"
  "SV-RULE-FIRE-PARTITION|the SV rules that NEVER FIRED on the corpus are CLASSIFIED and the classification is CONSUMED: the tracked partition is held consistent with the coverage artifact it derives from, every rule the certificate pass could not witness carries a hand adjudication with a measured LRM construct behind it, and the unwitnessed class must stay at zero (SV-CORPUS-GRAD.13c.2u; the coverage artifact published a flat never-fired list that NOTHING read, its headline 104 was stale at 137, and a large part of it cannot fire because PGEN's own LR eliminator authored or replaced those rules — \`casting_type\` reads never-fired while its nineteen _lr_* replacements carry every size cast — so an unclassified list reads as a defect surface and sends a reader hunting phantoms)|scripts/check_sv_rule_fire_partition.sh"
  "SCRATCH-SLOT-HEADER|the blessed throwaway scratch slot keeps its OPERATING MANUAL — the header block that is the only record of how to regenerate, drive and restore the slot, and of the rebuild-ast_pipeline-AFTER ordering trap — because the body is meant to be overwritten and the header is not (PARSE-HARNESS.11; measured 2026-08-15: an agent replaced the whole file, and the correct workflow ends in \`git checkout\`, so the loss can NEVER reach a commit for a commit-time gate to see — the probe-time tier in \`make focus_scratch\` is the one that catches it, and this tier catches a removal that IS committed)|scripts/check_scratch_slot_header.sh"
  "GENERATED-REPRODUCIBILITY|every artifact in the untracked generated/ tree is what HEAD's tracked source PRODUCES — not merely what it compiles into, and not merely unchanged since someone recorded a hash (ENGINE-UNIVERSAL-SERVICES.29; measured 2026-08-16: both annotation parsers carried a line the code generator CANNOT emit — grep -c 0, git log -S no commit ever — written from an uncommitted editor state, and they are the pair the annotation backend links to generate every OTHER parser, while layer A recorded 'generated/ FRESH' throughout)|scripts/check_generated_reproducibility.sh"
  "README-STABILITY|README.md stays a stable LANDING PAGE — both a line cap and a byte cap, because a line cap alone is measurably bypassable — at adoption layer-A MEMORY.md passed its 60-line cap carrying 138,403 unbounded bytes, a bypass since CLOSED by giving MEMORY-ARCH the same two caps (README-POLICY.2) — plus a changelog-leakage tripwire and a link back to the reviewed policy (README-POLICY.1; adopted at 510 lines/48,811 bytes with NO instrument watching size: the two guards that touch README.md audit doc PATHS and the root file SET)|scripts/check_readme_stability.sh"
  "SV-CONTRACT-CURRENCY|the SV downstream integration contract describes the grammar that is actually in the tree: every revision of grammars/systemverilog.ebnf since the register genesis is accounted for as a RELEASE (contract section + bug-ledger row) or as ACCEPT-SET-NEUTRAL, and a neutrality claim is CHECKED against the frontend's own raw_ast digest rather than believed (SV-CORPUS-GRAD.13c.2l; measured 2026-08-19: the contract said 1.0.183 while SEVEN semantically-distinct grammar revisions had shipped, FOUR of them REPLACING an AST shape a consumer was already reading, and one of those four moved ZERO verdicts — nothing compared the grammar's last-modified commit with the contract's, and the leaf tracking the population BY HAND went stale twice more inside the same week) ⛔ The digest is a function of the FRONTEND as well as of the grammar: a frontend change re-keys every earlier row with no grammar byte moving (measured 2026-09-03, EBNF-FRONTEND-SILENT-TRUNCATION.6), so the register declares \`# frontend_rekey: <sha>\` epochs and tier A does not re-derive commits at or before one, printing how many it skipped — history is kept, never rewritten, and the exemption is a number.|scripts/check_sv_contract_currency.sh"
  "SV-RELEASE-DISTANCE-CURRENCY|the SV release distance the SV parser book publishes — items = legs_unmet + bar_rows + open_leaves, the ONE number per turn the director asked for on 2026-09-17 (SV-CORPUS-GRAD.25) — is a re-derivation of the tracked tree (the status page's legs line, the three adjudication manifests, the two task trees) and the history it rests on has a last row that describes THIS tree: a number nothing re-derives goes stale silently, and a distance that drifts from the tree is worse than no distance|scripts/check_sv_release_distance.sh"
  "LOOKAHEAD-SLOT-TEMPLATES|no return template binds a LOOKAHEAD child: a lookahead is a positional child that binds an empty node, so a positional reference on a lookahead slot, a per-iteration slice whose K-th child is the guard or the separator the guard shifted, and a guard-opened group bound raw are all unreadable shapes; the auditor proves it can fail (--self-test) before reading the scoped grammars (SV-CORPUS-GRAD.3.61; measured 2026-09-10: TEN such sites had shipped in grammars/systemverilog.ebnf across releases 1.0.79, 1.0.191 and 1.0.210 and stayed green under every gate, because the accept set never moved and a consistently wrong tree is byte-identical to itself release after release - every parameter type T = int lost its default type for 150 releases). TWO INSTRUMENTS, COMPLEMENTARY BY CONSTRUCTION SINCE ENGINE-UNIVERSAL-SERVICES.106 (2026-09-15): this auditor re-tokenizes the grammar SPELLING and therefore declares a twelve-grammar scope list, excluding the bootstrap chain whose '(' token style it misreads; --lint-grammar's template_binds_lookahead_child reads the FRONTEND's own child numbering, covers every grammar the engine can load (the five bootstrap-chain grammars included, measured at 0) and GATES, but decides only what is STRUCTURAL. The SEPARATOR reading stays here because it is an INTENT inference: the corrected list_of_type_assignments writes \$2::3* over a group that still OPENS with a lookahead, so a structural rule of that shape would fire on the shipped grammar. On the founding population this auditor reads 10 and the engine lint reads 8, and the two it cannot reach are exactly the separator rows)|scripts/check_lookahead_slot_templates.sh"
  "GRAMMAR-CERT-CURRENCY|the published per-grammar certification table stays a DERIVATION of the tree, and the instrument that would notice is still ALIVE: tier 1 (0.27 s, every commit, no oracle) proves the book page carries exactly one well-formed DERIVED block, that the producer's --check is WIRED (statically -- the option variable is READ, not merely assigned -- and behaviourally -- it refuses a path that does not exist), that the published POPULATION equals the families that actually ship, and that no declared input leads the page past a budget; tier 2 (--oracle, 64.5 s MEASURED -- predicted 65 s, first measured 128.5 s because the red control paid for a whole second derivation to be told something a grep knows, fixed in the producer by refusing a block-less page at argument-parse time in 0.01 s) re-derives all nine rows and DIFFS them, after first driving the producer's own refusal arm so a green verdict cannot come from an instrument that says green to everything (GRAMMAR-CERT-STATUS.2). MEASURED twice over: the roster was DOC-ASSERTED and rotted (CHANGES.md: \"fully-certified-6 roster membership was doc-asserted only\"), then the derive-and-diff that replaced it was itself DELETED while its FLAG survived, so --check was accepted, printed a table and exited 0 on EVERY input -- including a nonexistent path -- for a whole commit, while the main book, the owning leaf and layer-A MEMORY.md all published that it \"refuses when the two disagree\" (GRAMMAR-CERT-STATUS.1b). HONEST BOUND, stated before the check is trusted: tier 1 is a staleness argument and inherits whatever tier 2 last established, exactly as PARSE-COST-RATCHET says of itself; generated/ is untracked, so a fresh clone reports the population arm NOT EVALUATED, loudly, never as a pass. 9/9 refusal arms observed firing via --self-test, including the two that reconstruct the .1b regression from both sides|scripts/check_grammar_certification.sh"
  "BASELINE-IDENTITY|a tracked baseline holding a value DERIVED from the tree says WHICH tree, and the enforcer RE-HASHES every input it declares on every run: a generic \`identity\` block (\`verified_at_commit\` + an \`inputs\` map of repo-root-relative path -> sha256) whose dependency set is DATA rather than hard-coded in a script, ONE shared verifier so every gate refuses in provably identical words, and a CLOSED two-sided population over rust/test_data/grammar_quality/ in which an entry with no verdict FAILS and a verdict naming no entry FAILS. ⛔⛔ The block answers TWO questions and the \`expectations\` field (\`confirmed\` or \`unconfirmed\`, with NO default) is the second: input digests say whether the inputs MOVED, never whether the numbers were ever RIGHT about them. Shipping without it inverted this doctrine on its own first customer (-0248, retracted by -0249) -- the gate printed \"identity fresh\" and then an unattributable drift, turning an honest vague RED into a confident WRONG answer. \`unconfirmed\` is RED for every consumer, never a waiver, so a baseline nobody can re-derive yet can still be watched for input drift and still name the leaf that owes the re-derivation. ⭐⭐ AND PROVENANCE DISAMBIGUATES A VERDICT RATHER THAN GATING WORK (SV-CORPUS-GRAD.13c.2x.4): the first cut made a moved input a FAILURE in an enforcer that runs from .githooks/pre-commit, so ONE COMMENT LINE in the SV grammar BLOCKED EVERY COMMIT -- for an edit the frontend strips. Now an input may be digested SEMANTICALLY (\`ebnf_raw_ast\`, the frontend's own envelope, the same definition SV-CONTRACT-CURRENCY uses), staleness is a printed NOTE inside a DERIVED budget of commits touching the declared inputs and a hard failure past it (so ROT stays impossible -- the founding artifact sat 69 revisions stale), and a gate MEASURES a stale baseline instead of refusing: green re-stamps it from that run's own numbers, red refuses as ambiguous, and the env-gated escape the old design needed is DELETED (SV-CORPUS-GRAD.13c.2x.2, director-ordered 2026-08-20; measured 2026-08-20: sv_cert_recognized_union_gate had been RED at HEAD for ELEVEN grammar revisions by 71 rules and 53 UNKNOWNs, every expected_* field an exact function of that grammar and not one byte in the file able to say the baseline was the stale half). ⛔ A block nobody READS is the defect, not the fix — SV-CORPUS-GRAD.13i measured SIX oracles already carrying a self-describing identity block, only ONE gate-checked and FOUR measurably stale — so a row registered anything but adopted that CARRIES a block is a hard failure, and the first adoption shipped with its consuming gate REFUSING TO MEASURE (exit 2, the published refusal code) until the identity verifies|scripts/check_baseline_identity.sh"
  "CORPUS-KEY-INTEGRITY|the corpus ANSWER KEY is checked like the instrument it is, and so is the instrument that checks it: tier A1 (always, corpus-INDEPENDENT, 0.1 s) runs the census self-test and refuses a shrunken arm set, a zero-arm 'pass' or an unparsable summary; tier A4 (also corpus-INDEPENDENT, it reads the tracked manifests) holds the PROVENANCE census the same way and pins its UNMATCHED residual under a ceiling -- a rise means the manifests gained a basis SHAPE nobody classified, so the published trust bound (93.8 % of the answer key rests on evidence OUTSIDE the standard: 627 clause-cited / 2287 tool-testimony / 7172 suite-convention / 4 unmatched, over 10 090 keyed rows) silently stopped covering the population; tier A2/A3 (0.49 s total) requires zero contradictory upstream-message classes, zero bases quoting evidence their own golden lacks, and the tracked census.md to be BYTE-IDENTICAL to a fresh derivation. Founded on the key measurably deciding wrong twice in three days (SV-CORPUS-GRAD.13e.3(a): two files, the same binary ~& operator, OPPOSITE expectations, the difference an iverilog flag the key never read; SV-0068: three rows keyed must_accept for text IEEE 1364-2005 cannot derive, sitting at \`match\` -- the STRONGEST verdict in the file -- for the whole campaign, because an expectation error in the ACCEPT direction produces no flag at all). ⛔⛔ AND THE FIRST CENSUS BUILT TO CATCH THAT WAS ITSELF WRONG TWICE INSIDE ONE COMMIT (CORPUS-KEY-AUDIT.1(a)) -- a 100 % false-positive rate, 2 of 2, and a message regex requiring an error:/sorry: tag while iverilog emits its bare parse refusal UNTAGGED, so \`syntax error\`, the most parse-relevant class in the corpus, was absent from the vocabulary its headline was measured over -- which is why A1 tests the census before A2 trusts its verdict. The vendored corpora are submodules, so a fresh clone reports A2/A3 NOT EVALUATED, LOUDLY, never as a pass and never as a commit-blocking failure; that refusal branch is EXERCISED by the self-test (a relocated census copy whose repo-root walk lands on no corpus), not assumed. 13/13 refusal arms observed firing via --self-test, including a GREEN control on the real tree so the refusals are not vacuous|scripts/check_corpus_key_integrity.sh"
  "SAMPLE-PROFILE-PARITY|every @sample annotation in a grammar still parses under the profiles its own BRANCH is live in — an @sample is a single PROFILE-BLIND string, so declaring a @profiles dialect NARROWS the language and silently strands every sample written against the wider one. Measured (SV-CORPUS-GRAD.13e.9): FOUR such samples on systemverilog cost TEN certificate rules, written 2026-04-22 and latent since the profile was registered on 2026-07-02 — 54 days — because NOTHING in the repository read @sample at all: no gate, no workflow, no hook, no lint. The class is created by an edit that is otherwise correct (adding a dialect), which is why nobody looks. ⛔ THE JOIN IS THE WHOLE DESIGN AND THE OBVIOUS ONE IS 100 % FALSE POSITIVES: @profiles is RULE-level while 43 of SystemVerilog 52 samples are BRANCH-level, so joining a branch sample against the rule set over-reports BY CONSTRUCTION — measured 115 checks / 8 reported / 0 true defects against the branch join 101 / 0 / 0, and those 8 are exactly the 7 that .13e.9 adjudicated BY HAND as branch-dead-sample-honest plus the 1 that .13e.10(c4) created. ⭐ ORACLE archetype, not a currency proxy: it re-executes the census and gates whether the samples PARSE, never whether the census was re-run. STAGED-DIFF-SCOPED for cadence — 33 s on systemverilog, so inert unless a grammar is staged, which was made affordable by moving the census into the engine (2 m 43 s to 33 s, PGEN-SV-CORPUS-GRAD-0308). A grammar with no @profiles is NOT EVALUATED, loudly, never a pass; a missing headline REFUSES rather than scoring, because a load failure and a parse rejection are indistinguishable at rc 1|scripts/check_sample_profile_parity.sh"
  "LR-ELIMINATION-RATCHET|a grammar edit may not RAISE the number of left-recursive cycles the elimination pass DECLINES. An unhandled cycle is not untidy: the runtime guard does not handle it, it REJECTS same-position re-entry, so every derivation needing the recursion at the seed position is UNREACHABLE and the grammar declares strictly more than its parser accepts — an UNDER-acceptance on the profiles being released. ⛔ FOUNDING MEASUREMENT (ENGINE-UNIVERSAL-SERVICES.50): ONE @profiles tag, the tag --lint-grammar itself DERIVES for constant_cast, moved systemverilog from left_recursion_unhandled=0 to 15 and left_recursion_eliminated 4 to 3 — while profile_orphans, the ERROR-class counter an operator would quote, went to 0, the lint still exited 0, and every registered doctrine stayed GREEN. Nothing in the repository read this counter. ⭐ GIT IS THE BASELINE: the comparison is staged content versus HEAD content of the SAME file, so there is no tracked artifact to go stale, no rebaseline step and no identity block — and both sides are linted with the same binary, which isolates the GRAMMAR axis by construction. ⭐ SHORT-CIRCUITED so the common case costs ONE lint: a staged grammar reading 0 cannot have risen INTO 0, and 0 is every shipping grammar today. It BLOCKS with no env escape, which is free on day one because ENGINE-UNIVERSAL-SERVICES.50(b) shipped the fix FIRST — the SV-CORPUS-GRAD.13e.11 rule that a guard is safe to make blocking over its whole population exactly when the fix precedes it. ⚠️ HONEST LIMIT: staged-scope-aware on GRAMMARS, so an ENGINE change that raises the counter without touching a grammar is not caught here|scripts/check_lr_elimination_ratchet.sh"
  "GAP-CLAIM-CENSUS|a task leaf that ADDS a nothing-checks-X claim records the CENSUS it rests on. Such a sentence is a UNIVERSALLY QUANTIFIED claim over the whole tree, not a description, and it is false the moment ONE reader exists; this repository published it wrong three times in three days (-0288 retracted by -0289, -0290 CLOSED AS REFUTED by -0294 once gather_verified_profile_proof_covered_rules turned out to cross the two, and one more caught in draft). STAGED-DIFF-SCOPED so the 81 unbacked claims of 242 already in docs/tasks never block, and calibrated by REPLAYING 150 real commits rather than an imagined phrasing: 95 added claim lines, 16 would have blocked in 14 commits, adjudicated one by one to 12 true positives. It catches the ACTIVE and the PASSIVE voice, so both founding sentences are in the fired set and two self-test arms pin them there verbatim|scripts/check_gap_claims.sh"
  "TABLE-ARITY-RATCHET|a staged markdown file may not RAISE the number of table rows whose cell count disagrees with their own header. GFM is TWO-SIDED and SILENT in both directions: a row with MORE cells than its own header has the excess DISCARDED -- not rendered, not warned about, and a dropped cell leaves no gap -- while a row with FEWER is silently PADDED, so a column simply is not there. The class breaks no build, fails no test and renders without complaint, which is how it reached 51 of 1 167 tracked .md files (136 OVER + 49 UNDER, measured 2026-08-27 by table_arity_population_sweep.sh with the two founding files already repaired) unnoticed; the evidence that nothing else caught it is BEHAVIOURAL rather than a grep -- on commit 2a61a0ea this driver reported ALL 30 doctrines PASS on a clean tree carrying 26 defective rows in a shipped contract. FOUNDING MEASUREMENT (LIVE-DOC-CONTAINMENT.8, 2026-08-24..27): docs/contracts/PGEN_RELEASED_PARSER_BUG_LEDGER.md -- the artifact the SystemVerilog release SHIPS to Nexsim -- had 26 of 197 rows losing their rightmost cells, SV-0052 losing FOUR so the last visible cell was a mid-row fragment instead of Notes, the column holding the consumer-impact statement; and docs/TASK_TREE.md, the index this project resumes from, had 14 of 67, the four widest being the four most ACTIVE trees. GIT IS THE BASELINE -- staged content vs HEAD content of the SAME file, so nothing rots, there is no rebaseline step and no identity block; a file already carrying defects may be edited, it may not gain another, and a NEW file is compared against ZERO because the author has just written every row. It BLOCKS with no env escape, free on day one by the SV-CORPUS-GRAD.13e.11 rule that a guard is safe to make blocking exactly when the fix precedes it: both founding files were taken to 0 first. Two measured traps are pinned by self-test arms -- an escaped pipe is NOT a separator (splitting on every one reads the ledger at 94 instead of 26, a 3.8x inflation over 75 correctly-escaped rows, pointing the author at the FIX as if it were the defect), and the leading AND trailing pipes are BOTH OPTIONAL in GFM, so a count derived from awk NF-2 reads a trailing-pipe-less row one LOW and it DISAPPEARS from the census -- a defect that was live in this repository own instrument and made it publish 25 of 197 for a population of 26. FOUR ARMS, because each one is blind to what the next one sees: a backtick imbalance carrying no pipe cannot move a cell count, and re-introducing the exact empty-code-span defect this repository shipped in -0014 left the arity census at 0 OVER / 0 UNDER with ALL 31 doctrines GREEN while both renderers saw it -- so a second arm ratchets the number of table cells holding an UNPAIRED backtick run. That arm carries its own correction: a backslash does NOT escape a code-span delimiter (CommonMark parses code spans before backslash escapes), and getting it wrong read the bug ledger at 4 unpaired cells where both renderers see 0, every one a correct span -- pinned by a self-test arm so it cannot come back. A COUNT IS NOT A SCHEMA, and the third and fourth arms exist because a row can land on its header's declared count and still be wrong -- a count says nothing about WHERE the boundaries fell (LIVE-DOC-CONTAINMENT.11). Arm three is STRUCTURAL and needs no per-table knowledge: it ratchets rows whose cell boundary falls INSIDE a code span, which is the root cause of the OVER class and also of the shapes that cancel. Replayed from 9dc3289d the resume index reads 0 OVER / 0 UNDER -- fully green under the doctrine as it shipped -- while THREE of its rows carry such a boundary, one of them GENERATED-LINT-CORRECTNESS, whose Status cell was split by a pipe inside a regex code span AND which was missing its frontier column entirely, one OVER and one UNDER cancelling to exactly the declared 5. Sized before it was made blocking: 118 such rows in 27 of 1 169 tracked files, of which 93 are ALSO arity-defective and 25, in 7 files, are arity-clean and provably invisible to arm one; both founding files read 0. Arm four is SEMANTIC: it reads a COLUMN. Predicates are IMPORTED from table_pipe_repair.py rather than re-declared, so the gate and the repair tool cannot drift apart about what a healthy column looks like, and each is matched against the WHOLE cell -- the registered predicate used to be a substring test, and MEASURED in both renderers 4 of 67 File cells held the link followed by frontier narration (1 424, 435, 1 247 and 56 717 authored characters) and passed it. Replayed from 8c3b93f9 that file passes arity, backtick AND in-span and fails four rows here. A link target is checked too, since a cell pointing at a path that does not exist satisfies every content predicate -- SCOPED to predicate-governed columns by measurement, because an unscoped sweep reports 192 of 236 links in the shipped bug ledger, all of them deliberate pointers into the sibling consumer repo that DOCPATH has already adjudicated as having no repo-relative equivalent. A table with NO registered predicate is NOT EVALUATED, loudly, counted in the summary line and never scored as a pass; and a predicate failing on a MAJORITY of its own table is an INSTRUMENT defect rather than a document one, so it is refused as NOT CREDIBLE and cannot block a commit on a misconfiguration. 29/29 arms observed firing via --self-test, including GREEN controls on the real tree for all four arms, THREE RED controls replayed from real git history rather than synthesised, and pins proving each arm catches what the ones before it cannot see|scripts/check_table_arity.sh"
  "FAMILY-STATUS-CURRENCY|every parser book's published per-family status block stays a DERIVATION of the tree, and the producer that derives it can still REFUSE. Origin: a direct director remark 2026-08-30 -- 'I have no idea for each parser the amount of work to reach full completion (Done) ... there seems to be no end in sight' -- answered by DONE-BAR-VISIBILITY .1/.2/.3 (the derivation: bar-leg state, corpus counts against a named denominator, and the finite list of open trees) and .9 (published in all ten parser books). This is what stops those ten pages becoming ten more hand-maintained numbers, which is not hypothetical: LIVE-MEANS-LIVE.1a measured 25 of 61 hand-maintained fields simply wrong, and SV-CORPUS-GRAD.13c.2z found the SystemVerilog book publishing release 1.0.183 against a shipped 1.0.192. THREE TIERS, each blind to what the next sees: (A) STRUCTURAL, no derivation -- the population is CLOSED and TWO-SIDED (every registered family has a page, every page belongs to a registered family), each page carries exactly ONE well-formed DERIVED block, and that block's BEGIN marker names the family whose book it sits in, so another family's block pasted into a page is caught for free; (B) the RED CONTROL, driven BEFORE the oracle is believed -- the producer's --check on a nonexistent path must exit 2, because GRAMMAR-CERT-STATUS.1b shipped a producer whose --check FLAG survived a rewrite that deleted its implementation and four different inputs all exited 0 for a whole commit; (C) the ORACLE -- --check-all re-derives all ten blocks AND the cross-family roster view in the platform book (DONE-BAR-VISIBILITY.5, one derive() per family, so the eleven surfaces cannot disagree by construction) and DIFFS them. It uses the all-families mode deliberately: the two audit runs are family-INDEPENDENT and are 2.3 s of the 3.4 s cost, so ten separate invocations would pay for them ten times and the doctrine would be too slow for every commit, which is how a check ends up behind a flag nobody sets. The BOOK half of the derivation is TRACKED-ONLY by construction -- legs 1 and the green-NOW half of leg 2 rest on untracked rust/target artifacts, so publishing this machine's reading would make this gate fail on a fresh clone. HONEST LIMIT: it holds the PUBLISHED block equal to what the producer derives today; whether the producer's inputs are right is their own doctrines' business|scripts/check_family_status.sh"
  "CORPUS-CENSUS-CURRENCY|a published corpus pass rate is RE-DERIVED from the tracked census that holds it, and the census still describes THIS tree. Founding measurement, DONE-BAR-VISIBILITY.3b, 2026-08-30: stimuli/vhdl/characterization/characterization.md is tracked and instructs its own reader, in its own words, to re-hash three declared inputs and re-measure rather than quote if any differs -- and nothing in the repository re-hashed them. The recorded generated-parser digest was a90ae37b while the tree carried 48a5d294, and a re-measure moved the census from 4 335 / 9 385 (31.6 pct) to 4 370 / 9 350 (31.9 pct): 35 rows, every one fail-to-pass and not one pass-to-fail, over 418 commits of which 72 touched rust/src and ZERO touched grammars/vhdl.ebnf. So the published VHDL pass rate was wrong for 22 days, in the flattering direction, on a 56-second measurement. FIVE ARMS, each blind to what the next sees: STRUCTURE (a report missing a table this doctrine reads REFUSES, it is never scored zero); ARITHMETIC (the outcome classes partition every row, the sub-corpus columns sum to the totals row, and each published rate equals its own quotient within half of its last digit -- the arm that catches a HAND-EDITED number, and LIVE-MEANS-LIVE.1a measured 25 of 61 hand-maintained fields simply wrong); GRAMMAR IDENTITY, a HARD failure priced by measurement rather than hope, since grammars/vhdl.ebnf has moved TWELVE times in the life of this repository and a grammar edit is exactly the event after which a pass rate must not be quoted; DENOMINATOR CURRENCY, which re-counts the corpus from the working tree per sub-corpus, because a denominator is the half of a pass rate nobody checks; and ENGINE STALENESS ON A DERIVED BUDGET, a NOTE inside the budget and a failure past it, because the generated parser moves whenever the ENGINE does and making that blocking would tax most commits here with a re-measure -- the mistake BASELINE-IDENTITY paid for when ONE COMMENT LINE in the SV grammar blocked every commit. The budget is the ONE MEASURED drift episode (72 engine commits, 35 moved rows, 0.26 pct, one direction), and its honest limit is stated in the gate: that is the size at which drift was DETECTED, not a size proven safe. NO SECOND ARTIFACT: the tracked report IS the census, the gate re-derives from it and scripts/report_family_status.sh publishes from the same file, with the two derivations held equal -- a machine-readable copy beside it would be a second thing to drift, which is the disease. Digests are not re-implemented: check_baseline_identity.sh --digest is called for every hash. The vendored corpora are submodules and generated/ is untracked, so an absent input is reported NOT EVALUATED, loudly, never as a pass. a self-test whose control COUNT is DERIVED and printed on every run -- never carried in its own headline -- plus a GREEN control on the real tracked report, and every RED arm driven against that real report through the schema seam; the controls found two defects in the gate before it shipped, including a heading reader that matched a SUFFIX so a report whose totals section had been renamed still read as having one. A CENSUS HAS A KIND, because a corpus with an ANSWER KEY is not the same measurement as one without and rendering both through one template publishes fields that do not mean what they say: DONE-BAR-VISIBILITY.3c added kind oracle_expectation for regex, whose key is PCRE2 10.47's own recorded compile verdicts, so its share IS a conformance share where the VHDL one is raw. Its freshness leg re-runs the normalizer into a SCRATCH directory in 0.11 s and compares all three tracked artifacts byte-for-byte, with ONE declared exclusion -- the summary key recording WHERE the run wrote, a property of the invocation, the same technique check_sv_corpus_denominator.sh uses for its own corpus-dependent column. That leg was IMPOSSIBLE until .3c fixed the producer: the tracked summary held ABSOLUTE paths into a foreign checkout on a different volume, so the artifact was a function of whose machine ran it. Its sharpest arm holds the published verdict tuple's cell count equal to a RE-DERIVED denominator, which is exactly what REGEX-ORACLE-ANCHOR-SYNC cannot see -- that doctrine compares the anchor to a TRACKED CONSTANT, so a moved corpus leaves the constant and the anchors agreeing with each other and both wrong. A declined case is counted, never dropped: 50 of 2 239 pattern specs are cases the census refused to ask, and a case nobody asked is not a case that passed. HONEST LIMIT: the verdict half is not re-executed (a cargo build plus a run over every case, measured 80 s and 5.5 GB peak); it was re-measured on HEAD for .3c and read 2189/1879/262/48, EXACTLY the published anchor -- unlike the VHDL census, that one was current. Eight further controls driven through the seam for this kind, including one proving the denominator-arithmetic arm fires ALONE, which needs a normalizer wrapper because any mutation of the tracked summary is caught upstream by freshness. RE-AUDITED UNDER A DIRECTOR CHALLENGE (DONE-BAR-VISIBILITY.3d): every published number re-derives exactly, ONE claim was CORRECTED and ONE real hole closed at zero cost. The corrected claim is the founding census -- it grepped for a path LITERAL while the repository's own corpus runner COMPOSES that path, so stimuli/run_external_corpus.sh reads the tracked report on every run and four other scripts read the same identity table: not-read-by-anything is FALSE and was never the claim worth making, while the narrower one this doctrine rests on was checked directly and survives -- the runner takes field 2 of that row, the PATH, and never field 3, the DIGEST. The hole: engine_paths counted rust/src alone, and the binary that emits the parser also has rust/build.rs and rust/Cargo.toml as inputs, so a narrow set undercounts and delays a NOTE becoming a FAILURE -- the permissive direction. Widened after measuring that the union over the founding window is STILL 72, so the calibration is unchanged and the scope strictly more conservative. TWO honest limits the first cut did not state are now in the header: the grammar arm hashes ONE FILE and is complete only for a grammar with no include (measured 0 for the shipped customer), and engine_paths is a declared set that is not proven exhaustive. A DENOMINATOR IS COUNTED THE PRODUCER'S WAY, AND THE WAY IS DECLARED (SV-CORPUS-GRAD.13m): denominator_source is filesystem, the default that walks the tree and leaves every earlier entry byte-for-byte unchanged, or lane_list, where the tracked list the producer reads IS the population. SystemVerilog's sv2005 lane is the second kind -- run_external_corpus.sh reads v2005_lane_files.tsv, which the adjudicator derives, so walking stimuli/sv/subs for it answers a different question than the producer asked. Measured under the lane's OWN -name '*.v' extension set the walk reads 360/3799/341 against a published 356/1909/341, so the filesystem source breaches 2 of 3 suites even under the reading most favourable to it, and the one suite where it agrees agrees by accident: on sv2v the two sets are IDENTICAL at 341. lane_list is a RE-DERIVATION and never a skip -- an arm that opts out is GATE-REACHABILITY wearing a census -- so it counts the list per suite, holds the published rows equal to it in BOTH directions, holds the total equal to the totals row, and confirms every listed path is a regular file the producer could have been handed; an unimplemented source REFUSES rather than falling through to the walk, and a declared list that is absent is a BREACH, because a census whose population cannot be re-derived is not current. Nine arms in the bank docs/tasks/artifacts/sv_corpus_grad/v2005_lane_denominator/probe.sh, driven through the schema seam against COPIES so no tracked file is ever mutated, and ARM 0 is the founding measurement re-derived: the same report under the filesystem source goes RED. The self-test's control COUNT is now DERIVED from the controls that register themselves rather than carried in its own headline. THE GRAMMAR ARM IS KEYED ON THE SEMANTIC DIGEST WHEN THE REPORT CARRIES ONE (SV-CORPUS-GRAD.13r): a report may record a grammar raw ast row -- sha256 of the EBNF frontend's own raw_ast envelope, the ONE definition check_baseline_identity.sh --digest ebnf_raw_ast owns and SV-CONTRACT-CURRENCY / PARSE-COST-RATCHET already key on -- and when the declaration names it (grammar_semantic_identity_row) and the digester can run, a moved envelope is the same HARD failure as before while bytes moved with the envelope unchanged is a NOTE: a comment or whitespace edit the frontend strips, so the language in the tree IS the language the report describes and no re-measure is owed. NOT a loosening: any production, terminal or annotation change moves the envelope. Measured on the founding pair -- .13p (a real grammar fix) moved bytes AND envelope and fails either way; .13q (one comment line) moved bytes only and under the byte key BLOCKED the commit until four corpus runs and two commits had produced byte-identical artifacts, the exact case BASELINE-IDENTITY's own registry text had already ruled one doctrine earlier. Over the whole SV history 4 of the 11 stale-by-bytes readings were this class (.13e.6(c)). Fallbacks are LOUD, never silent: a report with no semantic row, or a tree with no debug ast_pipeline, is judged on bytes exactly as before with the semantic arm reported as not evaluated. The verdict is a PURE function of four digests so the self-test drives every cell on literals (a None digest never equals None), and the bank docs/tasks/artifacts/sv_corpus_grad/semantic_grammar_identity/probe.sh drives the founding pair on report FIXTURES with every digest derived from the git blobs at run time -- including the arm that REMOVES the semantic row and requires the .13q NOTE to become a breach again, so the relief is earned by the row, not granted by default|scripts/check_corpus_census.sh"
  "LRM-CLAUSE-CITATION|a cited IEEE clause NUMBER contains the LRM LINE it is cited with. Founding measurement, SV-CORPUS-GRAD.13q, 2026-09-02: a conformance claim here is FOUR measurements wearing one sentence -- the quoted text, the LRM file, the line number and the clause number -- and only the first three are checkable by grep. SV-CORPUS-GRAD.13p located the gate-delay cardinality sentence at 1800-2017 section-28 md :396 and 1364-2005 section-7 md :376, quoted it correctly, and labelled it 28.16 / 7.14: a REAL clause (Gate and net delays) whose number sat four lines from the located text inside 28.3.3 own cross-reference. Seven cited lines, seven wrong clause labels, every quotation right, shipped to release ledger SV-0077, the downstream SystemVerilog contract, the parser book and a grammar comment. Nothing in the grammar fix was wrong, which is why the class needs a gate: a wrong LABEL on a right claim survives every other check here. IT JUDGES ONLY WHAT IT CAN BIND and prints the size of the rest -- a line reference is judged only when its file is pinned structurally (an explicit section md path, the clause-adjacent forms, or a bare backtick-colon continuing one inside a bounded span), when it sits in the clause own BRACKET SCOPE, and when the resolved file is CLAUSE-ADDRESSABLE; everything else is counted in no_line_ref / no_edition / annex_ref / unaddressable_section / unresolved_file and printed, because a census that gets cleaner because it stopped looking is the failure mode that looks most like success, and this instrument caught its own author committing it when judged rows fell 35 to 17 mid-fix while the report stayed green. THERE IS NO ALLOWANCE LIST, and that is the design: the two citation shapes that legitimately break the enclosure premise are recognised STRUCTURALLY, never by path -- the defined-here / absent-there sentence (defined in 8.26.1 but NOT referenced at section-8-classes md :95, two correct parentheticals about different places) is unbound by bracket scope, and a file that cannot answer for the cited clause is unbound by ADDRESSABILITY, asked per (file, CITED CLAUSE) and never per file: does this file carry any heading of that clause major at all. ⛔ SV-CORPUS-GRAD.13u CORRECTED THIS AND WITHDREW A PUBLISHED NUMBER: the first cut tested a FILE against its own FILENAME via the modal heading major and reported 17 of 124 vendored files mis-titled, which is FALSE -- the modal major measures which clause is biggest, not whether the filename lies, and section-15 opens at 15.1 with 26 clause-15 headings (correctly named, a missing SPLIT) while section-29 is 29.1 to 29.10 and is not defective at all; spanning is the NORM, 34 of 55, 25 of 41 and 17 of 28 per edition. The filename number is now read NOWHERE -- the section-vs-clause comparison went with it, having fired on two CORRECT citations of 11.4.12 into a file carrying 35 of its 39 headings in clause 11 -- and the corrected rule judges MORE (agree 33 to 35) with unaddressable_section falling 2 to 0, so the hole the first cut reported in its own reach was the instrument's and not the corpus's. What survives is at most 5 files in 1800-2017 and 2 in 1800-2023 whose filename number is not a clause they hold, each still owing individual adjudication, re-scoped onto SV-CORPUS-GRAD.13t. The first cut carried both shapes as seven hand-written exceptions keyed by line numbers that MOVE; a gate whose green depends on a hand-maintained exception list is not a gate, it is a promise -- and removing the list cost ZERO reach, agree is identical either way. A third structural rule is load-bearing for correctness rather than for exemptions: a heading whose major disagrees with its file own modal major is PDF-split noise and is skipped when resolving the enclosing clause, because v2005 section-7 carries four stray 2-delays / 3-delays headings that are fragments of 7.14 own prose, and reading one as the enclosing clause reports every citation past it as wrong. GROUND TRUTH runs on every invocation -- 14 pairs covering all three rules plus the founding 28.16 known-bad and an ancestor-citation known-good -- and a miss exits 7 MISCALIBRATED rather than reporting a clean tree; it caught its own author writing the noise pair off the FIRST stray heading instead of the innermost one. --self-test adds a RED control per structural rule, and SV-CORPUS-GRAD.13u made each arm carry its OWN SUBJECT: three synthetic probes driven through the real pipeline and asserted in BOTH directions, because when .13u corrected the addressability rule no citation in the repository landed on an unaddressable pair any more, so the tree-level mutation changed nothing and the arm correctly reported itself INERT rather than passing (SV-CORPUS-GRAD.87(e): a green mutation is a question about the CONFIGURATION before it is a verdict about the lock). The tree-level run is kept as corroboration and reports NOT EXERCISED, never a pass, when this repository does not contain the shape; a GREEN control asserts the tree re-reads identically afterwards. HONEST LIMIT, printed rather than hidden: it checks the clause-to-line relation only -- whether the quoted sentence says what the claim needs is still the LRM own business -- and no_line_ref is the size of what it declines to judge, so the reach is never mistaken for the population. Cost ~0.43 s over the whole tracked tree, no build, no parser|scripts/check_lrm_clause_citation.sh"
  "IDENTITY-CARRIER-CURRENCY|a tracked artifact that tells its reader to re-hash its declared inputs IS re-hashed, by a gate, over a population DERIVED on every run -- a promise nobody checks is a claim (SV-CORPUS-GRAD.13i). Founding measurement 2026-08-14: SIX live carriers under docs/tasks/artifacts and stimuli/*/characterization opened with an Instrument identity table and exactly ONE was gate-checked, and the one with a gate was the one that had never been stale. By 2026-09-03 three doctrines had grown readers for five of them and the last un-gated pair, dark_chained_only/{adjudication,summary}.md, had sat stale for 21 grammar revisions (16 days); re-derived, they moved ZERO verdict classes and six failure positions -- STALE, not WRONG, and nothing could have said which without a re-run. Population = every tracked .md under docs/tasks/artifacts and stimuli/*/characterization carrying the heading followed by sha256 rows (both the 3-column and the annotated 2-column table shapes); a path with a before/ or after/ component is a FROZEN snapshot, reported and never judged. Per row the SUBJECT is the LABEL, not the path cell (.13j(ii), now measured three times): a raw ast row is compared semantically via check_baseline_identity.sh --digest ebnf_raw_ast; parse binary and generated parser rows are NOTES (the shared probe moves with every family; engine drift is budgeted by CORPUS-CENSUS-CURRENCY); any other row is bytes and HARD -- unless the carrier is ALREADY judged by another registered oracle (derived from the registry script column, this gate excluded), in which case a byte mismatch is DEFERRED to that oracle with a note, because cost.md sample-inputs row digests the manifest ORDER plus every sampled file and PARSE-COST-RATCHET reads it fresh while a byte re-hash of its path cell reads moved; this gate is the guard on carriers NOBODY else checks. The message says STALE (describes a different tree) and never WRONG (the producer re-run decides). PGEN_IDENTITY_CARRIERS is the bank seam; --report prints every row verdict; the self-test drives every verdict cell on literals; the bank docs/tasks/artifacts/sv_corpus_grad/identity_carriers/probe.sh is 8/8 including the .13i(c) control -- the SV report as it stood at 0994c3c0 goes RED -- and an EMPTY population REFUSES rather than passing for free|scripts/check_identity_carriers.sh"
  "SV-STORE-GATE-BANK|the .13w store-gate explanation bank (docs/tasks/artifacts/sv_corpus_grad/store_gate/probe.sh) is RUN by a gate, every arm it declares -- it was RED for six commits (-0347 to -0354) because nothing invoked it, and a check nothing invokes is indistinguishable from no check (SV-CORPUS-GRAD.15); the judge needs exit 0 + a summary N/N as declared (fail=0) with N equal to the bank's own DECLARED + no FAIL arm line, and --self-test proves each refusal fires; where the release probe is not built the gate evaluates nothing and SAYS SO|scripts/check_sv_store_gate_bank.sh"
  "EBNF-ALTERNATIVE-PARITY|for every rule in every tracked grammar, the number of alternatives the SOURCE declares (the meta-parser generated from grammars/ebnf.ebnf, run by ebnf_dual_run_diff --emit-ast-json) equals the number the frontend's IR carries (ast_pipeline --emit-raw-ast-json: top-level pipe operators plus one) — mechanism-agnostic, so it catches a dropped alternative (SV-CORPUS-GRAD.3.19: a column-0 comment ended the body early) and an invented one (EBNF-FRONTEND-SILENT-TRUNCATION.6: three \`//\`-commented alternatives of parseable_source_item shipped LIVE for four months, in the token-position differential's UNVERIFIED tail) without knowing how the frontend erred; pairing (same rule names, same order) is checked first, include-directive grammars and grammars either reader refuses are NOT EVALUATED by name and counted, never passed; self-test drives both counters and every verdict cell on literals including the frozen pre-fix parseable_source_item envelope (source 1 vs IR 4) and a real-arm mutation (EBNF-FRONTEND-SILENT-TRUNCATION.1)|scripts/check_ebnf_alternative_parity.sh"
  "SV-RESERVED-WORDS|the SV grammar's two reserved-word regexes EQUAL the LRM tables they stand for -- IEEE 1800-2017/2023 Table B.1 (248 words) for the sv_2017/sv_2023 profiles and IEEE 1364-2005 Annex B (124) for verilog_2005 -- DERIVED from the in-repo LRM text on every run and compared as SETS in both directions, with --self-test proving a planted missing word and a planted foreign word are each refused. Founding measurement, SV-CORPUS-GRAD.3.37, 2026-09-04: the hand-typed SV list held 173 of the 248, so reg global;, i.super.i = 1;, function new; input x; (an ordinary function NAMED new) and var final; all parsed with the keyword bound as an identifier; no certificate, corpus lane or lint could see it because every one of them consumes the same identifier rule -- a keyword the identifier rule does not refuse IS an identifier|scripts/check_sv_reserved_words.sh"
  "SV-KEYWORD-VERSIONS|the preprocessor's IEEE 1800-2017 §22.14 per-version keyword tables (rust/src/sv_keyword_versions.rs) EQUAL the tables the LRM carries, derived on every run and compared as SETS in both directions -- the tables decide which identifiers a begin_keywords region hands the parser as ESCAPED identifiers (SVPP-EXPANSION.8), so a wrong table is an accept-set change nothing else can see. THE PDF-to-md EXTRACTION MERGES TABLE BODIES AND DISPLACES THEM PAST THE PROSE, so the two split points are DERIVED, each by an oracle blind to the others: Table 22-2 vs 22-3 is not separable by ANY property of the 1800 text (the merged body is strictly alphabetical, so every split point is admissible) and is split by IEEE 1364-2005 §19.11 Tables 19-2/19-3/19-4, a different standard and a different PDF, whose difference is then checked EQUAL to the merged body; Table 22-4 vs 22-5 has no second document and is split at the UNIQUE cut that leaves both tables strictly increasing -- the body carries exactly one descent (within then accept_on) and a body whose descent count is not (tables minus one) is REFUSED rather than guessed. The sum of all six tables is held equal to Annex B Table B.1 (248), which is §22.14.9's own sentence -- the full set is listed in Annex B, which reflects the combination of all version tables -- and the 1800-2017 and 1800-2023 extractions are held equal word for word. The profile map and the admitted specifier lists are held equal to the grammar's own @profile_alias and keywords_version_specifier_* declarations, so the stage that RENDERS and the stage that PARSES cannot disagree about a profile. It also proves the ONE direction the preprocessor cannot render can never bite: text can unreserve a keyword and cannot reserve a non-keyword, so a region richer than the parse profile would be applied only half way -- the arm admitted_specifiers_are_subsets derives each profile's set and each admitted specifier's set from the tables and FAILS if any admitted specifier reserves a word the profile does not, which turns a runtime WARNING into a structural guarantee (admitted implies subset, because an edition lists only versions at or below itself; measured 14 corpus occurrences above verilog_2005, every one already a parse rejection). --self-test drives eight refusal arms (a planted missing word, a planted foreign word, a planted wrong profile mapping, a planted missing admitted specifier, a planted profile admitting a RICHER version, a two-descent body, and GREEN controls on the real tree)|scripts/check_sv_keyword_versions.sh"
  "DATA-LOCALITY|no tracked LIVE code path creates project-owned scratch OUTSIDE the repository volume -- the director's standing policy (project instructions §13, project_north_star: data stays on the repo volume), which until now was enforced by nobody. FOUNDING MEASUREMENT (DATA-LOCALITY.1, 2026-09-15): 19 live sites in 11 files -- 7 std::env::temp_dir(), 7 tempfile::tempdir(), 4 bare or off-volume mktemp templates, 1 Python TemporaryDirectory() with no dir= -- and ONE of them is PRODUCTION, not a test: the parse harness built its generated parser, its scratch crate and its compiled binary under the system temp root, which on this host is a different volume. ⛔⛔ THE FINDING WAS PUBLISHED EIGHTEEN COMMITS EARLIER AS A 26-TEST HOUSEKEEPING ITEM IN ONE MODULE, ROUTED, FIXED IN THAT MODULE, AND NEVER RE-READ -- the route outlived its own fix while the class it belonged to was never counted. ⛔⛔⛔ AND THE CLASSIFIER WAS WRONG THREE TIMES BEFORE IT WAS TRUSTED, EACH CUT PINNED AS A SELF-TEST ARM, because mktemp has four spellings and only the ARGUMENT decides: cut 1 matched the CALL and counted every repo-rooted template as a breach (52 reported, 4 real); cut 2 required a terminator after the flags and read the opening QUOTE of a template as the end of the call; cut 3 decided by the NAME of the variable a template used, so three CORRECT derived-path sites were reported as breaches. The third cut is the one that stops being a spelling list: a variable reference is RESOLVED against its own assignments in the same file before the verdict is taken, and the question is where the path RESOLVES, never what the call looks like. TWO POPULATIONS, and the second is not a backlog: docs/tasks/artifacts/** holds one-shot PROBE scripts kept as the evidence of a measurement already taken (67 sites in 46 files), so rewriting them would falsify the record of what was run -- they are COUNTED and CLASSIFIED on every run, never edited, so the exemption is a number rather than a silence. The live surface is held at ZERO, which is free on day one by the SV-CORPUS-GRAD.13e.11 rule that a guard is safe to make blocking exactly when the fix precedes it: all 19 were repaired first, including the production one, behind a single helper (pgen::repo_scratch) so the answer to where scratch goes cannot drift one convenience call at a time. 11 self-test arms: 10 classifier cases covering all four mktemp spellings and both directions of a derived variable, plus a REACH arm that fails if the frozen population ever reads zero -- a census that gets clean by looking less is the failure mode that looks most like success|scripts/check_data_locality.sh"
  "PIPELINE-LANE-CURRENCY|the preprocess-to-parse lane's published numbers are a RENDER of two dumps under a DERIVED context, and none of the three is carried by hand -- and so is the RE-ADJUDICATION of the deferred population under the pipeline (SVPP-EXPANSION.6a: pipeline_readjudication.md + .tsv, arm 3, the same derive-and-diff): the tracked include context (stimuli/sv/pipeline_context.tsv + the per-file rows) equals a fresh derivation from the corpus by stimuli/sv/pipeline_context.py, and the tracked stimuli/sv/characterization/pipeline_characterization.md equals a fresh render of the lane dump and the raw dump by stimuli/sv/pipeline_vs_raw.py with the probe-digest row and the Measured-at-HEAD line masked as provenance (IDENTITY-CARRIERS keeps that row; the HEAD line names the commit the RENDER ran on, so unmasked it made the report DRIFT on every commit after the one that published it). Founding measurement, SVPP-EXPANSION.4/.4b, 2026-09-09: the first lane over the 4 157 UVM + OpenTitan rows the raw answer key carries with NO verdict read pass 850 -> 1 097, and the .5 engine fixes moved it to 1 101 the same day -- a published copy of either number would have been wrong within hours. The dumps are .gitignored, so a tree without them is NOT EVALUATED, loudly, never scored; --self-test drives a GREEN control, a RED context mutation, a RED report mutation and the absent-dump path on copies|scripts/check_pipeline_lane_currency.sh"
)

fail=0
declare -a report=()

for entry in "${DOCTRINES[@]}"; do
  # ⛔ THE FIELD SEPARATOR IS `|`, SO A `|` INSIDE A DESCRIPTION SPLITS THE ROW IN THE WRONG PLACE
  # and `script` ends up holding a fragment of prose. The failure is loud but the MESSAGE is wrong:
  # it reads "registered enforcer missing or not executable: <a paragraph of English>", which sends
  # the reader looking for a missing file. Measured 2026-08-20 while registering `BASELINE-IDENTITY`
  # (`SV-CORPUS-GRAD.13c.2x.2`) — the third escaping defect this registry has had, after the
  # unescaped backticks that ran a command substitution (`-0241`). Diagnose it here instead.
  if [ "$(printf '%s' "$entry" | tr -cd '|' | wc -c | tr -d ' ')" != "2" ]; then
    report+=("✗ FAIL  <meta:registry> — a registry row does not have exactly 2 '|' separators, so"
             "        its fields split in the wrong place. A '|' inside the description is the"
             "        usual cause; the row begins: ${entry:0:60}…")
    fail=1
    continue
  fi
  IFS='|' read -r id proves script <<< "$entry"
  if [ ! -x "$ROOT/$script" ]; then
    report+=("✗ FAIL  ${id} — registered enforcer missing or not executable: ${script}")
    fail=1
    continue
  fi
  if out="$("$ROOT/$script" 2>&1)"; then
    report+=("✓ PASS  ${id} — ${proves}")
  else
    report+=("✗ FAIL  ${id} — ${proves}")
    printf '%s\n' "$out" >&2
    fail=1
  fi
done

# ------------------------------------------------------------------ meta-check: registry ESCAPING
# ⛔⛔ THE REGISTRY EXECUTED ITS OWN DESCRIPTIONS, FOUR TIMES, AND THE THIRD FIX CITED THE SECOND AS
# PRIOR ART WITHOUT CHECKING FOR IT. A doctrine description is prose inside a DOUBLE-QUOTED bash
# string, where four characters stay live: $ ` \ and ". MEASURED 2026-08-25 (DOCTRINE-GAP-OWNERSHIP
# .16): the CORPUS-KEY-INTEGRITY row carried 4 unescaped backticks, so bash ran `match` and
# `syntax error` as command substitutions at ARRAY-DEFINITION time and the published description lost
# those exact words -- "sitting at  -- the STRONGEST verdict". Both surviving sentences still read as
# grammatical English, which is why re-reading the report could never catch it, and the missing token
# was precisely the technical term the sentence existed to carry.
#
# ⛔⛔ IT FAILED IN THE PASSING DIRECTION: the driver printed two "command not found" lines to stderr
# -- which every caller that greps the verdict discards -- and exited 0. `bash -n` was clean
# throughout. This is valid bash doing exactly what it was told.
#
# ⭐⭐ IT READS THE SOURCE FILE, NOT "${DOCTRINES[@]}", AND THAT IS THE WHOLE DESIGN. By the time the
# array can be inspected bash has ALREADY performed the substitution: the array holds the RESULT, with
# the offending words gone. A guard over the expanded values is blind to this defect BY CONSTRUCTION
# -- it would inspect the evidence after the fire. Only the unexpanded source text can answer.
#
# ⭐ IT GUARDS THE CLASS, NOT THE MEMBER -- which is the whole complaint against the third fix, whose
# guard counted `|` separators only and left the cited backtick defect free to recur (it recurred
# within days). Refused here: any unescaped ` $ or ", and any backslash escaping something other than
# those four. MEASURED over the registry before wiring it: 30 rows, of which 1 carried 4 unescaped
# backticks (fixed in the same commit) and 4 more carried 24 CORRECTLY escaped ones, with ZERO
# unescaped $ or " anywhere and only \" (8) and \` (28) in use. ⇒ the convention is already known and
# followed, and after the fix this arm fires on NOTHING -- the SV-CORPUS-GRAD.13e.11 condition for a
# guard that is safe to make blocking: the fix precedes it.
#
# ⚠️ Honest limit: this checks the ROWS, not the driver's other double-quoted strings, and it cannot
# tell a deliberate substitution from an accidental one -- it refuses both. In a registry of reviewed
# prose that is the right trade; a row that genuinely needs a computed value should build it above the
# array, not inside a description.
registry_escape_findings="$(awk '
  /^DOCTRINES=\(/ { inreg = 1; next }
  /^\)$/          { if (inreg) inreg = 0 }
  inreg && /^  "/ {
    body = $0
    sub(/^[ \t]*"/, "", body)
    sub(/"[ \t]*$/, "", body)
    id = body
    sub(/\|.*$/, "", id)
    i = 1; bad = ""
    while (i <= length(body)) {
      c = substr(body, i, 1)
      if (c == "\\") {
        n = substr(body, i + 1, 1)
        if (n != "\"" && n != "`" && n != "$" && n != "\\") bad = bad " backslash-before-<" n ">"
        i += 2
        continue
      }
      if (c == "`")       bad = bad " unescaped-backtick"
      else if (c == "$")  bad = bad " unescaped-dollar"
      else if (c == "\"") bad = bad " unescaped-doublequote"
      i++
    }
    if (bad != "") printf "        line %d (%s):%s\n", NR, id, bad
  }
' "$SELF")"
if [ ! -r "$SELF" ]; then
  # ⛔ A check that cannot inspect its subject must SAY SO, not pass — the rule the mirror and
  # book-count arms below already follow. Without this branch an unreadable SELF is indistinguishable
  # from a clean registry, and that is how the RED control first passed against a copy it never read.
  printf 'registry-escaping: cannot read the driver source at %s, so the registry text was NEVER inspected\n' "$SELF" >&2
  report+=("✗ FAIL  <meta:registry-escaping> — the driver could not read its OWN source; the registry was not inspected")
  fail=1
elif [ -n "$registry_escape_findings" ]; then
  {
    echo "registry rows carry SHELL-ACTIVE text that bash expands at array-definition time:"
    printf '%s\n' "$registry_escape_findings"
    echo "  Escape it: \` -> \\\` , \$ -> \\\$ , \" -> \\\" . The published description silently LOSES"
    echo "  the substituted words while still reading as grammatical English, and the driver exits 0."
  } >&2
  report+=("✗ FAIL  <meta:registry-escaping> — a registry description would be EXPANDED by bash (see above)")
  fail=1
else
  report+=("✓ PASS  <meta:registry-escaping> — no registry row carries unescaped \` \$ or \" (${#DOCTRINES[@]} rows)")
fi

# ------------------------------------------------------------------ meta-check: the human mirror
# The registry above is the SOURCE OF TRUTH and the header has always CLAIMED that
# DOCTRINE_ENFORCEMENT.md §10 is "kept in lockstep" with it. MEASURED 2026-07-29
# (CI-PARITY-GATE-ROT.15): it was not — 3 registered doctrines had no row (`TASK-ACCEPTANCE`,
# `ROUTING-EVIDENCE`, `DESTRUCTIVE-TARGET-GUARD`) and 1 row named `DIAG-TOOLBOX-EVIDENCE`, an id the
# registry no longer carries. A documented promise nobody checks is the exact rot this driver exists
# to end, one level up. ⛔ The assertion lives HERE and is about a DIFFERENT file, deliberately: an
# assertion about a file cannot live inside that file as a literal (docs/decisions/
# reference_self_referential_assertion_is_unsound.md).
# ⚠️ Honest limit, stated not discovered: this proves the ID SETS agree, not that each row's prose is
# accurate. Row text is reviewed, not gated.
MIRROR="DOCTRINE_ENFORCEMENT.md"
mirror_ids="$(sed -n '/^## 10\. The live PGEN instance/,/^## 11\./p' "$ROOT/$MIRROR" 2>/dev/null \
              | sed -n 's/^| `\([A-Z][A-Z0-9+-]*\)` |.*/\1/p' | LC_ALL=C sort -u)"
registry_ids="$(printf '%s\n' "${DOCTRINES[@]}" | cut -d'|' -f1 | LC_ALL=C sort -u)"
if [ -z "$mirror_ids" ]; then
  report+=("✗ FAIL  <meta:mirror> — ${MIRROR} §10 yielded ZERO doctrine rows. A check that cannot"
           "        inspect its subject must SAY SO, not pass: either the section was renamed or its"
           "        table shape changed. Fix the extraction or the section, do not delete the check.")
  fail=1
else
  only_registry="$(LC_ALL=C comm -23 <(printf '%s\n' "$registry_ids") <(printf '%s\n' "$mirror_ids"))"
  only_mirror="$(LC_ALL=C comm -13 <(printf '%s\n' "$registry_ids") <(printf '%s\n' "$mirror_ids"))"
  if [ -n "$only_registry" ] || [ -n "$only_mirror" ]; then
    [ -n "$only_registry" ] && printf 'doctrine registered but ABSENT from %s §10: %s\n' \
      "$MIRROR" "$(printf '%s' "$only_registry" | tr '\n' ' ')" >&2
    [ -n "$only_mirror" ] && printf 'row in %s §10 naming a doctrine NOT registered: %s\n' \
      "$MIRROR" "$(printf '%s' "$only_mirror" | tr '\n' ' ')" >&2
    report+=("✗ FAIL  <meta:mirror> — the registry and its ${MIRROR} §10 mirror disagree (see above)")
    fail=1
  else
    report+=("✓ PASS  <meta:mirror> — ${MIRROR} §10 lists exactly the ${#DOCTRINES[@]} registered doctrines")
  fi
fi

# ------------------------------------------------------------------ meta-check: the BOOK's count
# ⛔ A THIRD COPY OF THE ROSTER SIZE LIVES IN THE BOOK, AND IT WAS MEASURABLY STALE.
# `docs/book/src/gate-flow.md` publishes the number of registered doctrines twice — it is the
# reader-facing surface, and per the standing directive the book is the primary window into this
# project. Measured 2026-08-16 (`ENGINE-UNIVERSAL-SERVICES.29`(b)): the book said **19** while the
# registry held **20**. Nothing compared them: the mirror check above governs
# `DOCTRINE_ENFORCEMENT.md` only, so the book was free to drift, and it did — silently, and in the
# direction that makes the project look LESS guarded than it is.
# ⭐ MARKER-SCOPED, NOT SPELLING-MATCHED. The count is wrapped in `<!-- DOCTRINE-COUNT -->` … so
# prose around it can be rewritten freely without touching this check. Enumerating sentence
# spellings is exactly what made `LIVE-DOC-CURRENCY`'s instrument B measure one population as 10,
# then 16, then 18 — every miss silent in the passing direction.
# ⚠️ It asserts the COUNT, not the roster: the book is a narrative surface and is not asked to carry
# 21 ids. `DOCTRINE_ENFORCEMENT.md` §10 is where the id set is gated, above.
BOOK="docs/book/src/gate-flow.md"
if [ -f "$ROOT/$BOOK" ]; then
  book_counts="$(grep -o '<!-- DOCTRINE-COUNT -->\**[0-9]\{1,4\}' "$ROOT/$BOOK" | grep -o '[0-9]\{1,4\}$')"
  if [ -z "$book_counts" ]; then
    report+=("✗ FAIL  <meta:book-count> — ${BOOK} carries no <!-- DOCTRINE-COUNT --> marker. A check that"
             "        cannot inspect its subject must SAY SO, not pass: re-wrap the published count, or"
             "        the book is free to drift from the registry again (it was 19 against a registry of 20).")
    fail=1
  else
    bad_counts=""
    while IFS= read -r n; do
      [ "$n" = "${#DOCTRINES[@]}" ] || bad_counts="$bad_counts $n"
    done <<< "$book_counts"
    if [ -n "$bad_counts" ]; then
      printf 'book publishes doctrine count(s)%s but the registry holds %s — update %s\n' \
        "$bad_counts" "${#DOCTRINES[@]}" "$BOOK" >&2
      report+=("✗ FAIL  <meta:book-count> — ${BOOK} publishes a stale registered-doctrine count (see above)")
      fail=1
    else
      # ⛔ `printf '%s' | wc -l` counts NEWLINES, so it reads one short on a trailing-newline-free
      # string — it printed "1 marked site(s)" for two. Count the lines themselves.
      report+=("✓ PASS  <meta:book-count> — ${BOOK} publishes ${#DOCTRINES[@]}, matching the registry ($(printf '%s\n' "$book_counts" | grep -c .) marked site(s))")
    fi
  fi
else
  report+=("✗ FAIL  <meta:book-count> — ${BOOK} is missing, so the published doctrine count cannot be checked")
  fail=1
fi

# ------------------------------------------------- meta-check: the BOOK's CONTENT (not its number)
# ⛔⛔ THE COUNT ARM ABOVE WAS GREEN FOR MONTHS WHILE 14 OF THE 33 REGISTERED DOCTRINES APPEARED
# NOWHERE IN THE BOOK AT ALL. Measured 2026-08-30 (`DOCTRINE-GAP-OWNERSHIP.20`), per-doctrine over
# `docs/book/src/*.md`, with every candidate re-searched under its component halves and its
# enforcer's filename so a spelling miss could not manufacture the result: present 19, ABSENT 14.
# Median debt 32 days, max 69, 410 doctrine-days; three of them absent since the doctrine framework's
# own founding commit. A doctrine could be registered, enforced on every commit, mirrored two-sided
# into DOCTRINE_ENFORCEMENT.md §10 -- and never named in the reader-facing book, with every
# meta-check green. ⇒ the book's NUMBER was gated and the book's CONTENT was not.
#
# ⭐ THE COUNT ARM IS NOT DELETED, IT IS JOINED. A number that is right is still worth holding; it
# was simply never coverage. The two arms fail for different reasons and that is the point.
#
# ⛔ DIRECTOR-ORDERED, and the reason given is the binding one: *"the doctrines shall be documented
# in the top level mdbook because you keep talking about these 33 doctrines that are passing, so I
# asked myself, are these doctrines described, documented somewhere."* The book is the director's
# only window into this project, so a count they cannot resolve into descriptions is a disclosure
# loss, not a cosmetic gap.
#
# THREE ARMS, cheapest first, each blind to what the next one sees:
#   A  the RED CONTROL. `report_doctrines.sh --check <path that does not exist>` must exit 2.
#      Driven BEFORE the oracle is believed, because a sibling producer kept its `--check` FLAG
#      after a rewrite deleted the diff and then exited 0 on every input for a whole commit
#      (`GRAMMAR-CERT-STATUS.1b`). A green verdict from an instrument that says green to everything
#      is worth nothing.
#   B  the POPULATION, held TWO-SIDED over the WHOLE PAGE -- every registered doctrine has a
#      section, every doctrine-shaped section names a registered doctrine. ⭐ It scans the whole
#      page rather than the derived block DELIBERATELY: a hand-written section pasted OUTSIDE the
#      block is invisible to the diff in arm C, and a stale hand-written doctrine section is
#      precisely the rot this chapter is derived to avoid.
#   C  the ORACLE. Re-derive the roster and DIFF it against what is published.
# ⚠️ Honest limit, stated not discovered: this holds the published chapter equal to what the two
# tracked sources say TODAY. Whether a given description is DEEP ENOUGH is a review judgement and is
# not gated -- the chapter derives and publishes its own depth census instead, naming every
# description still under the one-clause floor, so thinness is visible rather than silent.
BOOK_CHAPTER="docs/book/src/the-enforced-doctrines.md"
DOCTRINE_REPORTER="scripts/report_doctrines.sh"
if [ ! -x "$ROOT/$DOCTRINE_REPORTER" ]; then
  report+=("✗ FAIL  <meta:book-content> — ${DOCTRINE_REPORTER} is missing or not executable, so the"
           "        book's doctrine roster was NEVER checked. A check that cannot inspect its subject"
           "        must SAY SO, not pass.")
  fail=1
elif [ ! -f "$ROOT/$BOOK_CHAPTER" ]; then
  report+=("✗ FAIL  <meta:book-content> — ${BOOK_CHAPTER} is missing. The book publishes a doctrine"
           "        COUNT the reader cannot resolve into descriptions, which is the defect"
           "        DOCTRINE-GAP-OWNERSHIP.20 was opened on.")
  fail=1
else
  # --- arm A: the producer must still be able to REFUSE -------------------------------------------
  bc_red_out="$(bash "$ROOT/$DOCTRINE_REPORTER" --check "$ROOT/rust/target/doctrine_chapter_no_such_page.md" 2>&1)"
  bc_red_rc=$?
  if [ "$bc_red_rc" -ne 2 ] || [[ "$bc_red_out" != *"no published page at"* ]]; then
    printf 'book-content: the producer refusal arm did NOT fire: --check on a nonexistent page\n' >&2
    printf '              exited %s (want 2). Its green verdicts cannot be trusted until it can\n' "$bc_red_rc" >&2
    printf '              refuse. Output was:\n%s\n' "$bc_red_out" >&2
    report+=("✗ FAIL  <meta:book-content> — ${DOCTRINE_REPORTER} could not be made to refuse (see above)")
    fail=1
  else
    # --- arm B: the population, two-sided, over the WHOLE page ------------------------------------
    bc_page_ids="$(grep -o '^### `[A-Z][A-Z0-9+-]*`' "$ROOT/$BOOK_CHAPTER" | tr -d '#` ' | LC_ALL=C sort -u)"
    bc_reg_ids="$(printf '%s\n' "${DOCTRINES[@]}" | cut -d'|' -f1 | LC_ALL=C sort -u)"
    if [ -z "$bc_page_ids" ]; then
      report+=("✗ FAIL  <meta:book-content> — ${BOOK_CHAPTER} carries ZERO doctrine sections. A check that"
               "        cannot inspect its subject must SAY SO, not pass: re-derive the chapter with"
               "        'bash ${DOCTRINE_REPORTER} --markdown'.")
      fail=1
    else
      bc_only_reg="$(LC_ALL=C comm -23 <(printf '%s\n' "$bc_reg_ids") <(printf '%s\n' "$bc_page_ids"))"
      bc_only_page="$(LC_ALL=C comm -13 <(printf '%s\n' "$bc_reg_ids") <(printf '%s\n' "$bc_page_ids"))"
      if [ -n "$bc_only_reg" ] || [ -n "$bc_only_page" ]; then
        [ -n "$bc_only_reg" ] && printf 'doctrine registered but with NO section in %s: %s\n' \
          "$BOOK_CHAPTER" "$(printf '%s' "$bc_only_reg" | tr '\n' ' ')" >&2
        [ -n "$bc_only_page" ] && printf 'section in %s naming a doctrine NOT registered: %s\n' \
          "$BOOK_CHAPTER" "$(printf '%s' "$bc_only_page" | tr '\n' ' ')" >&2
        report+=("✗ FAIL  <meta:book-content> — the registry and the book chapter's roster disagree (see above)")
        fail=1
      # --- arm C: re-derive and DIFF ---------------------------------------------------------------
      elif bc_out="$(bash "$ROOT/$DOCTRINE_REPORTER" --check "$ROOT/$BOOK_CHAPTER" 2>&1)"; then
        report+=("✓ PASS  <meta:book-content> — ${BOOK_CHAPTER} describes exactly the ${#DOCTRINES[@]} registered doctrines, and equals a fresh derivation")
      else
        printf '%s\n' "$bc_out" >&2
        report+=("✗ FAIL  <meta:book-content> — ${BOOK_CHAPTER} is OUT OF SYNC with the registry (see above)")
        fail=1
      fi
    fi
  fi
fi

printf '\n================ DOCTRINE ENFORCEMENT REPORT ================\n' >&2
for line in "${report[@]}"; do printf '  %s\n' "$line" >&2; done
printf '============================================================\n' >&2

# ------------------------------------------------------------------ scope note: what did NOT run
# ⭐ THIS TREE'S FOUNDING PRINCIPLE, APPLIED TO THE DRIVER ITSELF: *a check that cannot run must SAY
# SO, not return green.* Some registered enforcers judge the STAGED diff. Under the pre-commit hook
# that is the change being made; on a hosted `push` (E4) the index is EMPTY, so they exit 0 having
# evaluated nothing — and a green tick would otherwise imply they were satisfied.
# ⛔ DERIVED from each enforcer's own source, not hand-listed, so a staged-scope doctrine added later
# is named here by construction — the same reason E4 must call this driver rather than enumerate it.
# ⚠️ Honest limit: the classifier is a source-level heuristic (does the enforcer read the index?). A
# mislabel costs an inaccurate NAME in an informational note; it never changes a verdict.
staged_count="$(git -C "$ROOT" diff --cached --name-only 2>/dev/null | wc -l | tr -d ' ')"
if [ "${staged_count:-0}" -eq 0 ]; then
  vacuous=()
  for entry in "${DOCTRINES[@]}"; do
    IFS='|' read -r id _proves script <<< "$entry"
    if grep -qE -- '--cached|--staged|diff-index' "$ROOT/$script" 2>/dev/null; then
      vacuous+=("$id")
    fi
  done
  if [ "${#vacuous[@]}" -gt 0 ]; then
    printf 'scope: no staged changes — %d of %d doctrines are scoped to the STAGED diff and therefore\n' \
      "${#vacuous[@]}" "${#DOCTRINES[@]}" >&2
    printf '       evaluated NOTHING here: %s\n' "$(printf '%s ' "${vacuous[@]}")" >&2
    printf '       Their PASS above is vacuous, not evidence. They bind at commit time (E3) and on a\n' >&2
    printf '       hosted push only for whatever that push actually stages.\n' >&2
  fi
fi
# ⭐ The same principle for enforcers that judge with the RELEASE PROBE (SV-CORPUS-GRAD.15): a hosted
# checkout builds nothing, so a gate whose LIVE arms parse with rust/target/release/parseability_probe
# exits 0 there having judged nothing. DERIVED from each enforcer's own source (does it name the probe?),
# never hand-listed; the same honest limit as above — a mislabel is an inaccurate NAME in a note.
if [ ! -x "${PGEN_RELEASE_PROBE:-$ROOT/rust/target/release/parseability_probe}" ]; then
  unbuilt=()
  for entry in "${DOCTRINES[@]}"; do
    IFS='|' read -r id _proves script <<< "$entry"
    if grep -qE -- 'rust/target/release/parseability_probe' "$ROOT/$script" 2>/dev/null; then
      unbuilt+=("$id")
    fi
  done
  if [ "${#unbuilt[@]}" -gt 0 ]; then
    printf 'scope: the release probe (rust/target/release/parseability_probe) is NOT BUILT here — %d of %d doctrines\n' \
      "${#unbuilt[@]}" "${#DOCTRINES[@]}" >&2
    printf '       judge with it and evaluated NOTHING live: %s\n' "$(printf '%s ' "${unbuilt[@]}")" >&2
    printf '       Their PASS above is vacuous, not evidence. They bind on every clone that has built it (E3).\n' >&2
  fi
fi
if [ "$fail" -eq 0 ]; then
  printf 'doctrines: ALL %d enforced doctrines PASS.\n' "${#DOCTRINES[@]}" >&2
else
  printf 'doctrines: ✗ one or more doctrines FAILED — commit/merge blocked. Fix above, do not bypass.\n' >&2
fi
exit "$fail"
